from pathlib import Path
import base64, gzip, sys
path = Path(sys.argv[1])
text = path.read_text()
start = text.index("new_upsert = r'''function buildTrackedUpsertStatement")
end = text.index("new_verify = r'''", start)
replacement = gzip.decompress(base64.b64decode("")).decode()
text = text[:start] + replacement + text[end:]
old_map = '      const statements = batch.rows.map((row) => buildTrackedUpsertStatement({\n        runId: input.claim.runId,\n        tableName: sourceTable.name,\n        columns,\n        primaryKeyColumns: sourceTable.primaryKeyColumns,\n        row,\n        deferredSelfColumns: deferredNames,\n        batchSequence,\n      }));\n'
new_map = '      const statements = batch.rows.flatMap((row) => [\n        buildChangeSnapshotStatement({\n          runId: input.claim.runId,\n          tableName: sourceTable.name,\n          columns,\n          primaryKeyColumns: sourceTable.primaryKeyColumns,\n          row,\n          batchSequence,\n        }),\n        buildUpsertStatement({\n          tableName: sourceTable.name,\n          columns,\n          primaryKeyColumns: sourceTable.primaryKeyColumns,\n          row,\n          deferredSelfColumns: deferredNames,\n        }),\n        buildMigratedSnapshotStatement({\n          runId: input.claim.runId,\n          tableName: sourceTable.name,\n          columns,\n          primaryKeyColumns: sourceTable.primaryKeyColumns,\n          row,\n        }),\n      ]);\n'
if old_map not in text:
    raise SystemExit("tracked-upsert map anchor missing")
text = text.replace(old_map, new_map, 1)
path.write_text(text)
